from specflow.refmodel.temporal import after, edges, eventually, worst

def decide(trace):
    def _holds(cond):
        def p(row):
            return all(
                row['outputs'].get(k, row['inputs'].get(k)) == v
                for k, v in cond.items())
        return p

    # "an active (non-NOP) command" was normalized as cmd=1, which is
    # I2C_CMD_START -- the one command during which the controller drives
    # SDA low itself, so "the controller expects SDA to be high" is
    # definitionally false there. The requirement's first disjunct is about
    # a transmitted high bit (din=1) read back low, which only a WRITE
    # (I2C_CMD_WRITE = 4) does.
    active = _holds({'cmd': 4, 'ena': 1, 'nReset': 1, 'rst': 0})

    alt1 = _holds({'din': 1, 'scl_i': 1, 'sda_i': 0})

    rose_sda = set(edges(trace, 'sda_i', 'rise'))

    def alt2(row):
        return row['edge'] in rose_sda and row['inputs'].get('scl_i') == 1

    def opens(row):
        return active(row) and (alt1(row) or alt2(row))

    def closes(row):
        return row['outputs'].get('cmd_ack') == 1 or row['outputs'].get('al') == 1

    windows = after(trace, opens, until=closes)

    return worst([
        eventually(w, lambda r: r['outputs'].get('al') == 1,
                   after_activation=True, strong=True)
        for w in windows
    ])
